{
  "policy_type": "rules",
  "name": "policy_ep_40",
  "rules": [
    {
      "if": [
        {"feature": "y", "op": "<", "value": 0.5},
        {"feature": "vy", "op": "<", "value": -0.5},
        {"feature": "theta", "op": ">", "value": 0.1}
      ],
      "then": 2
    },
    {
      "if": [
        {"feature": "x", "op": "<", "value": 0.1},
        {"feature": "vx", "op": ">", "value": 0.5}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "x", "op": ">", "value": -0.1},
        {"feature": "vx", "op": "<", "value": -0.5}
      ],
      "then": 1
    },
    {
      "if": [
        {"feature": "vy", "op": ">", "value": -0.5},
        {"feature": "theta", "op": "<", "value": 0.1},
        {"feature": "omega", "op": "<", "value": 0.1}
      ],
      "then": 0
    },
    {
      "if": [
        {"feature": "left_leg", "op": "==", "value": 1},
        {"feature": "right_leg", "op": "==", "value": 1}
      ],
      "then": 0
    }
  ],
  "default_action": 0,
  "notes": "This new policy is influenced by the need to improve landing stability and reduce crashes. It incorporates rules that focus on maintaining a gentle descent (vy < -0.5) and controlling the lander angle (theta > 0.1). The previous policies were not available, but the design is based on common failure patterns observed in typical landing scenarios, aiming to enhance the agent's learning performance by encouraging safe landing behaviors."
}

